('q_prir-7-prvoci-bezobratli-nizsi_0','Kolik buněk má prvok?',ARRAY['tisíc','jednu','dvě','miliardu']::TEXT[],1,'Prvoci jsou jednobuněční.',1,ARRAY[]::TEXT[],NULL,0,'c_prir-7-prvoci-bezobratli-nizsi',NULL,NOW()),
('q_prir-7-prvoci-bezobratli-nizsi_1','Který prvok způsobuje malárii?',ARRAY['trepka','améba','krásnoočko','zimničky (Plasmodium)']::TEXT[],3,'Přenáší ho komár rodu Anopheles.',1,ARRAY[]::TEXT[],NULL,1,'c_prir-7-prvoci-bezobratli-nizsi',NULL,NOW()),
('q_prir-7-prvoci-bezobratli-nizsi_2','Do které skupiny patří žížala?',ARRAY['kroužkovci','členovci','měkkýši','hlístice']::TEXT[],0,'Tělo je článkované.',1,ARRAY[]::TEXT[],NULL,2,'c_prir-7-prvoci-bezobratli-nizsi',NULL,NOW()),
('q_prir-7-prvoci-bezobratli-nizsi_3','Čím se živí žahavci?',ARRAY['jen rostlinami','mrtvými zvířaty','kořistí, kterou chytají a paralyzují','slunečním svitem']::TEXT[],2,'Žahavé buňky.',2,ARRAY[]::TEXT[],NULL,3,'c_prir-7-prvoci-bezobratli-nizsi',NULL,NOW()),
('q_prir-7-prvoci-bezobratli-nizsi_4','Který živočich je žahavec?',ARRAY['sladkovodní slávka','pijavice','žížala','medúza']::TEXT[],3,'Medúzy a koráli.',2,ARRAY[]::TEXT[],NULL,4,'c_prir-7-prvoci-bezobratli-nizsi',NULL,NOW()),
('q_prir-7-prvoci-bezobratli-nizsi_5','Jak se pohybuje trepka?',ARRAY['brvami','bičíkem','křídly','nohama']::TEXT[],0,'Brvy.',2,ARRAY[]::TEXT[],NULL,5,'c_prir-7-prvoci-bezobratli-nizsi',NULL,NOW()),
('q_prir-7-prvoci-bezobratli-nizsi_6','Který parazit žije ve střevě člověka a je dlouhý jako páska?',ARRAY['tasemnice','pijavice','škrkavka','ploštěnka']::TEXT[],0,'Tasemnice (ploštěnec).',3,ARRAY[]::TEXT[],NULL,6,'c_prir-7-prvoci-bezobratli-nizsi',NULL,NOW()),
('q_prir-7-prvoci-bezobratli-nizsi_7','Který parazit patří mezi hlístice?',ARRAY['motolice','škrkavka','tasemnice','pijavice']::TEXT[],1,'Škrkavka je hlístice.',3,ARRAY[]::TEXT[],NULL,7,'c_prir-7-prvoci-bezobratli-nizsi',NULL,NOW()),
