('q_prir-7-prvoci-bezobratli-nizsi_9','Jak se nazývá žížalí pás, který tvoří kokon?',ARRAY['hltan','kloaka','pásemec','ploutev']::TEXT[],2,'Pásemec.',4,ARRAY[]::TEXT[],NULL,9,'c_prir-7-prvoci-bezobratli-nizsi',NULL,NOW()),
